{"implementation":"def solve(case):
    segments = case.get('segments')
    budget = case.get('budget')
    if segments is None or budget is None:
        raise ValueError("Missing required fields")
    for seg in segments:
        for key in ('name','importance','minimum','capacity'):
            if key not in seg:
                raise ValueError(f"Segment missing {key}")
        if not isinstance(seg['importance'], (int,float)) or not isinstance(seg['minimum'], int) or not isinstance(seg['capacity'], int):
            raise ValueError("Invalid types")
        if seg['minimum'] < 0 or seg['capacity'] < seg['minimum']:
            raise ValueError("Invalid minimum/capacity")
    total_min = sum(s['minimum'] for s in segments)
    total_cap = sum(s['capacity'] for s in segments)
    if budget < total_min or budget > total_cap:
        raise ValueError("Budget out of feasible range")
    alloc = [s['minimum'] for s in segments]
    remaining = budget - total_min
    n = len(segments)
    while remaining > 0:
        best_idx = -1
        best_score = -1.0
        for i, seg in enumerate(segments):
            if alloc[i] >= seg['capacity']:
                continue
            next_pos = alloc[i] + 1
            score = seg['importance'] / next_pos
            if score > best_score or (score == best_score and i < best_idx):
                best_score = score
                best_idx = i
        if best_idx == -1:
            raise ValueError("Cannot allocate remaining budget")
        alloc[best_idx] += 1
        remaining -= 1
    result_alloc = [{'name': segments[i]['name'], 'allocated': alloc[i]} for i in range(n)]
    names = [s['name'] for s in segments]
    total_allocated = sum(alloc)
    return {
        'allocations': result_alloc,
        'name_mapping': names,
        'total': total_allocated
    }"}
